# patch-claude-nvidia.ps1 - Single-file installer for Claude-NVIDIA proxy
# Usage:
#   powershell -ExecutionPolicy Bypass -File patch-claude-nvidia.ps1
#   powershell -ExecutionPolicy Bypass -File patch-claude-nvidia.ps1 -Uninstall

param(
    [string]$InstallDir = (Join-Path $env:USERPROFILE ".claude-nvidia"),
    [int]$ProxyPort = 18888,
    [switch]$Uninstall
)

$ErrorActionPreference = "Stop"
$NpmBin = Join-Path $env:APPDATA "npm"

function WOk([string]$m)   { Write-Host -Object ("  [OK]  " + $m) -ForegroundColor Green }
function WFail([string]$m) { Write-Host -Object ("  [FAIL] " + $m) -ForegroundColor Red }
function WInfo([string]$m) { Write-Host -Object ("  [..] " + $m) -ForegroundColor Yellow }
function WStep([string]$m) { Write-Host ""; Write-Host -Object ("  >>> " + $m) -ForegroundColor Cyan }

Write-Host ""
Write-Host "  Claude-NVIDIA Proxy Installer" -ForegroundColor Cyan
Write-Host "  Anthropic-to-OpenAI translation proxy for Claude Code" -ForegroundColor Cyan
Write-Host ""

if ($Uninstall) {
    WStep "Uninstalling claude-nvidia"
    if (Test-Path $InstallDir) {
        Remove-Item $InstallDir -Recurse -Force
        WOk "Removed $InstallDir"
    } else {
        WInfo "Install dir not found"
    }
    foreach ($f in @("claude-nvidia.cmd","claude-nvidia.ps1","claude-nvidia-proxy.cmd","claude-nvidia-proxy.ps1")) {
        $fp = Join-Path $NpmBin $f
        if (Test-Path $fp) { Remove-Item $fp -Force; WOk "Removed $fp" }
    }
    Write-Host ""
    Write-Host "  Uninstall complete." -ForegroundColor Green
    exit 0
}

WStep "Preflight checks"
$nodeVer = & node --version 2>$null
if (-not $nodeVer) { WFail "Node.js not found. Install Node.js 18+"; exit 1 }
$major = [int]($nodeVer -replace "^v","").Split(".")[0]
if ($major -lt 18) { WFail "Node.js too old, need 18+"; exit 1 }
WOk "Node.js $nodeVer"
$claudeCmd = Get-Command claude -ErrorAction SilentlyContinue
if (-not $claudeCmd) { WFail "claude not in PATH. Install: npm i -g @anthropic-ai/claude-code"; exit 1 }
WOk "Claude Code found"
if (-not (Test-Path $NpmBin)) { New-Item -ItemType Directory -Path $NpmBin -Force | Out-Null }
WOk "npm bin: $NpmBin"

# === EMBEDDED proxy.mjs ===
$PROXY_B64 = ""

# === EMBEDDED opencode.json ===
$CONFIG_B64 = ""

WStep "Installing files"
if (-not (Test-Path $InstallDir)) { New-Item -ItemType Directory -Path $InstallDir -Force | Out-Null }

$proxyBytes = [System.Convert]::FromBase64String($PROXY_B64)
$proxyText = [System.Text.Encoding]::UTF8.GetString($proxyBytes)
[IO.File]::WriteAllText((Join-Path $InstallDir "proxy.mjs"), $proxyText, [System.Text.UTF8Encoding]::new($false))
WOk "proxy.mjs"

$configBytes = [System.Convert]::FromBase64String($CONFIG_B64)
$configText = [System.Text.Encoding]::UTF8.GetString($configBytes)
[IO.File]::WriteAllText((Join-Path $InstallDir "opencode.json"), $configText, [System.Text.UTF8Encoding]::new($false))

$cfg = $configText | ConvertFrom-Json
$defModel = $cfg.model
$pCount = ($cfg.provider.PSObject.Properties | Measure-Object).Count
$mCount = 0
foreach ($pv in $cfg.provider.PSObject.Properties) {
    $mCount += ($pv.Value.models.PSObject.Properties | Measure-Object).Count
}
WOk "opencode.json - $pCount providers, $mCount models"

$pkgJson = '{"name":"claude-openai-proxy","version":"1.0.0","type":"module","main":"proxy.mjs"}'
[IO.File]::WriteAllText((Join-Path $InstallDir "package.json"), $pkgJson)
WOk "package.json"

WStep "Creating launchers"

$proxyPath = (Join-Path $InstallDir "proxy.mjs")

# claude-nvidia.cmd
$cmdLines = @(
    '@echo off'
    'setlocal EnableDelayedExpansion'
    ("set PROXY_PORT=" + $ProxyPort)
    ("set PROXY_SCRIPT=" + $proxyPath.Replace("\"," \\"))
    'curl -s http://localhost:%PROXY_PORT%/health >nul 2>&1'
    'if %errorlevel% neq 0 ('
    '    start /B "" node "%PROXY_SCRIPT%" %PROXY_PORT% 2>nul'
    '    set R=0'
    '    :w'
    '    timeout /t 1 /nobreak >nul'
    '    curl -s http://localhost:%PROXY_PORT%/health >nul 2>&1'
    '    if %errorlevel% equ 0 goto :ok'
    '    set /a R+=1'
    '    if !R! lss 10 goto :w'
    '    echo Proxy start failed'
    '    exit /b 1'
    '    :ok'
    ')'
    'set ANTHROPIC_BASE_URL=http://localhost:%PROXY_PORT%'
    'set ANTHROPIC_API_KEY=sk-proxy-local'
    ("set ANTHROPIC_MODEL=" + $defModel)
    ("set ANTHROPIC_SMALL_FAST_MODEL=" + $defModel)
    'set DISABLE_PROMPT_CACHING=1'
    'set CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC=1'
    'set DISABLE_ERROR_REPORTING=1'
    'claude %*'
)
$cmdText = $cmdLines -join "`r`n"
[IO.File]::WriteAllText((Join-Path $NpmBin "claude-nvidia.cmd"), $cmdText, [System.Text.Encoding]::ASCII)
WOk "claude-nvidia.cmd"

# claude-nvidia.ps1
$ps1Lines = @(
    '# claude-nvidia PowerShell wrapper'
    ("$" + "proxyScript = '" + $proxyPath + "'")
    ("$" + "port = " + $ProxyPort)
    'try { $null = Invoke-WebRequest "http://localhost:$port/health" -TimeoutSec 1 -UseBasicParsing -ErrorAction Stop }'
    'catch {'
    '    Start-Process -FilePath "node" -ArgumentList "$proxyScript","$port" -WindowStyle Hidden'
    '    for ($i = 0; $i -lt 15; $i++) {'
    '        Start-Sleep -Milliseconds 500'
    '        try { $null = Invoke-WebRequest "http://localhost:$port/health" -TimeoutSec 1 -UseBasicParsing -ErrorAction Stop; break } catch {}'
    '    }'
    '}'
    '$env:ANTHROPIC_BASE_URL = "http://localhost:$port"'
    '$env:ANTHROPIC_API_KEY = "sk-proxy-local"'
    ("$" + "env:ANTHROPIC_MODEL = '" + $defModel + "'")
    ("$" + "env:ANTHROPIC_SMALL_FAST_MODEL = '" + $defModel + "'")
    '$env:DISABLE_PROMPT_CACHING = "1"'
    '$env:CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC = "1"'
    '$env:DISABLE_ERROR_REPORTING = "1"'
    '& claude @args'
)
$ps1Text = $ps1Lines -join "`n"
[IO.File]::WriteAllText((Join-Path $NpmBin "claude-nvidia.ps1"), $ps1Text, [System.Text.UTF8Encoding]::new($false))
WOk "claude-nvidia.ps1"

# claude-nvidia-proxy.cmd
$proxyCmdText = "@echo off`r`nnode `"" + $proxyPath.Replace("\","\\") + "`" " + $ProxyPort + " %*"
[IO.File]::WriteAllText((Join-Path $NpmBin "claude-nvidia-proxy.cmd"), $proxyCmdText, [System.Text.Encoding]::ASCII)
WOk "claude-nvidia-proxy.cmd"

# claude-nvidia-proxy.ps1
$proxyPs1Text = "& node `"" + $proxyPath + "`" " + $ProxyPort + " @args"
[IO.File]::WriteAllText((Join-Path $NpmBin "claude-nvidia-proxy.ps1"), $proxyPs1Text, [System.Text.UTF8Encoding]::new($false))
WOk "claude-nvidia-proxy.ps1"

WStep "Quick proxy test"
$testOk = $false
try {
    $r = Invoke-WebRequest -Uri ("http://localhost:" + $ProxyPort + "/health") -TimeoutSec 2 -UseBasicParsing -ErrorAction Stop
    if ($r.StatusCode -eq 200) { $testOk = $true }
} catch {
    $tp = Start-Process -FilePath "node" -ArgumentList ("`"" + (Join-Path $InstallDir "proxy.mjs") + "`""),$ProxyPort -WindowStyle Hidden -PassThru
    for ($i = 0; $i -lt 15; $i++) {
        Start-Sleep -Milliseconds 500
        try {
            $r = Invoke-WebRequest -Uri ("http://localhost:" + $ProxyPort + "/health") -TimeoutSec 1 -UseBasicParsing -ErrorAction Stop
            if ($r.StatusCode -eq 200) { $testOk = $true; break }
        } catch {}
    }
    if ($tp -and -not $tp.HasExited) { $tp.Kill() }
}
if ($testOk) { WOk "Proxy responds on port $ProxyPort" }
else { WFail "Proxy did not respond" }

Write-Host ""
Write-Host "  Installation complete!" -ForegroundColor Green
Write-Host ""
Write-Host "  Usage:" -ForegroundColor White
Write-Host "    claude-nvidia              # Start with default model" -ForegroundColor Gray
Write-Host "    claude-nvidia-proxy        # Run proxy only" -ForegroundColor Gray
Write-Host ""
Write-Host ("  Default model: " + $defModel) -ForegroundColor White
Write-Host ("  Providers:     " + $pCount) -ForegroundColor White
Write-Host ("  Models:        " + $mCount) -ForegroundColor White
Write-Host ("  Install dir:   " + $InstallDir) -ForegroundColor White
Write-Host ("  Proxy port:    " + $ProxyPort) -ForegroundColor White
Write-Host ""
Write-Host "  To uninstall:" -ForegroundColor White
Write-Host "    powershell -ExecutionPolicy Bypass -File patch-claude-nvidia.ps1 -Uninstall" -ForegroundColor Gray
Write-Host ""